import type { ReactNode } from "react";

export interface AlertProps {
  children: ReactNode;
  variant?: "default" | "destructive" | "success";
  className?: string;
}

export function Alert({ children, variant = "default", className }: AlertProps) {
  return (
    <div
      className={cn(
        "rounded-md border p-4 flex items-start gap-3",
        variant === "destructive" && "bg-destructive/10 border-destructive text-destructive",
        variant === "success" && "bg-primary/10 border-primary text-primary",
        variant === "default" && "bg-muted border-border text-foreground",
        className
      )}
      role={variant === "destructive" ? "alert" : undefined}
    >
      {children}
    </div>
  );
}

export function AlertTitle({ children, className }: { children: ReactNode; className?: string }) {
  return <div className={cn("font-semibold text-base", className)}>{children}</div>;
}

export function AlertDescription({ children, className }: { children: ReactNode; className?: string }) {
  return <div className={cn("text-sm", className)}>{children}</div>;
}
